<?php declare(strict_types=1); namespace App\Providers; use Core\Foundation\ServiceProvider; use Core\Http\Router; class RouteServiceProvider extends ServiceProvider { public function boot(): void { $router = $this->app->get(Router::class); foreach (['routes/web.php', 'routes/admin.php', 'routes/api.php'] as $file) { $path = $this->app->basePath($file); if (is_file($path)) { $callback = require $path; if (is_callable($callback)) { $callback($router); } } } $router->loadModuleRoutes(); } } 